import './App.css';
import Navbar from './components/Navbar/Navbar';

import React, { useState } from 'react';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import Switch from '@mui/material/Switch';
import CssBaseline from '@mui/material/CssBaseline';
import useMediaQuery from '@mui/material/useMediaQuery';
import Hero from './components/Hero/Hero';

function App() {

  const [prefersDarkMode, setDarkMode] = useState(false);
  const [changeBG, setChangeBG] = useState(false);

  const theme = React.useMemo(
    () =>
      createTheme({
        // palette: {
        //   mode: prefersDarkMode ? 'dark' : 'primary',
        // },
        palette: 
        {
          mode,
          ...(mode === 'light'
            ? {
                // palette values for light mode
                primary: amber,
                divider: amber[200],
                text: {
                  primary: grey[900],
                  secondary: grey[800],
                },
              }
            : {
                // palette values for dark mode
                primary: deepOrange,
                divider: deepOrange[700],
                background: {
                  default: deepOrange[900],
                  paper: deepOrange[900],
                },
                text: {
                  primary: '#fff',
                  secondary: grey[500],
                },
              }),
        },   
      }),
    [prefersDarkMode],
  );

  const handleDarkMode = (event) => {
    setDarkMode(!prefersDarkMode);
    setChangeBG(!changeBG);
  };
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline >
        <div className="App" >
          <Navbar changeBG = { changeBG } theme = { theme } handleDarkMode= { handleDarkMode } prefersDarkMode = { prefersDarkMode }/>
          <Hero changeBG = { changeBG }/>


        </div>
       </CssBaseline> 
    </ThemeProvider>

  );
}

export default App;
